def find_components(color):
    visited = set()
    components = []

    def dfs(start_r, start_c):
        stack = [(start_r, start_c)]
        comp = set([(start_r, start_c)])
        while stack:
            r, c = stack.pop()
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                    if grid[nr][nc] == color and (nr, nc) not in visited:
                        visited.add((nr, nc))
                        comp.add((nr, nc))
                        stack.append((nr, nc))
        return comp

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == color and (r, c) not in visited:
                comp = dfs(r, c)
                if comp:
                    components.append(comp)

    return components

# Function to check if a component is a U-shape
def is_ushape(comp):
    if len(comp) < 4:
        return False

    rows_set = set(r for r, c in comp)
    cols_set = set(c for r, c in comp)
    min_r, max_r = min(rows_set), max(rows_set)
    min_c, max_c = min(cols_set), max(cols_set)

    col_counts = {}
    for r, c in comp:
        col_counts[c] = col_counts.get(c, 0) + 1
    spine_cols = [c for c, count in col_counts.items() if count == max(col_counts.values())]

    if len(spine_cols) > 2:
        return False
    spine_col = spine_cols[0]

    cells_per_spine_row = {}
    for r, c in comp:
        if c == spine_col:
            # Count all cells in this row (including arms)
            for dc in range(-5, 5):
