                    if (r, spine_col + dc) in comp:
                        cells_per_spine_row[r] = cells_per_spine_row.get(r, 0) + 1

    if len(cells_per_spine_row) < 2:
        return False

    sorted_rows = sorted(cells_per_spine_row.keys())

    # Check if spine has arms on both sides
    has_left_arm = any(c < spine_col for r, c in comp)
    has_right_arm = any(c > spine_col for r, c in comp)

    return has_left_arm and has_right_arm

